<script setup>
import BrandLogo from '../components/BrandLogo.vue';
import { ref, reactive, computed, watch, onMounted, onUnmounted } from 'vue';
import { services } from '../lib/barber';
import { t,language,toggleLanguage,today,api,useTeam } from '../lib/state';
const {team,error:teamError}=useTeam();
const serviceId=ref('signature'),preferred=ref('marco'),date=ref(today()),time=ref(''),slots=ref([]),loading=ref(false),busy=ref(false),error=ref(''),success=ref(null),activeSection=ref('');
const customer=reactive({name:'',email:'',phone:'',notes:''});
const eligible=computed(()=>(team.value||[]).filter(p=>p.serviceIds.includes(serviceId.value)));
const barberId=computed(()=>eligible.value.find(p=>p.id===preferred.value)?.id||eligible.value[0]?.id||'');
const barber=computed(()=>team.value?.find(p=>p.id===barberId.value));
const service=computed(()=>services.find(s=>s.id===serviceId.value));
const nav=[{id:'experience',label:'EXPERIENCE'},{id:'services',label:'SERVICES'},{id:'artists',label:'BARBERS'},{id:'book',label:'BOOK NOW'}];
const pretty=value=>{const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`;};
watch([serviceId,barberId,date,success],async(_,__,cleanup)=>{
  let active=true;cleanup(()=>active=false);time.value='';slots.value=[];
  if(!barberId.value||!date.value){loading.value=false;return;}loading.value=true;error.value='';
  try{const result=await api(`/api/availability?date=${date.value}&barber=${barberId.value}&service=${serviceId.value}`);if(active)slots.value=result.slots;}
  catch(e){if(active)error.value=e.message;}finally{if(active)loading.value=false;}
},{immediate:true});
function choose(person){if(!person.serviceIds.length)return;if(!person.serviceIds.includes(serviceId.value))serviceId.value=person.serviceIds[0];preferred.value=person.id;}
async function book(){if(!time.value||!barberId.value)return;busy.value=true;error.value='';try{const name=barber.value?.name;const result=await api('/api/appointments',{...customer,serviceId:serviceId.value,barberId:barberId.value,date:date.value,time:time.value});success.value={...result,name};}catch(e){error.value=e.message;}finally{busy.value=false;}}
let frame=0;
function updateActive(){frame=0;const line=(document.querySelector('.wire-header')?.getBoundingClientRect().height||84)+100;let current='';for(const {id} of nav)if((document.getElementById(id)?.getBoundingClientRect().top??Infinity)<=line)current=id;if(scrollY+innerHeight>=document.documentElement.scrollHeight-2)current='book';activeSection.value=current;}
const schedule=()=>{if(!frame)frame=requestAnimationFrame(updateActive);};
onMounted(()=>{updateActive();addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);});
onUnmounted(()=>{cancelAnimationFrame(frame);removeEventListener('scroll',schedule);removeEventListener('resize',schedule);});
</script>
<template>
<main class="wire-site" id="top">
<header class="wire-header"><a href="#top" class="wire-center-logo" :aria-label="t('Steve\'s Barbershop home')"><BrandLogo /></a><nav class="wire-nav" :aria-label="t('Main navigation')"><a v-for="item in nav" :key="item.id" :href="'#'+item.id" :class="{active:activeSection===item.id}" :aria-current="activeSection===item.id?'location':undefined">{{t(item.label)}}</a></nav><button class="language-toggle" @click="toggleLanguage" :aria-label="language==='en'?'Cambiar a español':'Switch to English'">{{language==='en'?'ES':'EN'}}</button></header>
<section class="wire-hero" :aria-label="t('Steve\'s Barbershop New York')"><div class="wire-hero-photo"><img src="https://images.unsplash.com/photo-1599351431202-1e0f0137899a?w=2000&q=85&fit=crop" :alt="t('Interior of a barber shop')"><span>{{t('NEW YORK · BY APPOINTMENT')}}</span></div><div class="wire-hero-copy wire-white-lines"><span>{{t('A BETTER STANDARD')}}</span><span>{{t('OF GROOMING')}}</span><span>{{t('IN NEW YORK')}}</span></div><a class="wire-hero-cta" href="#book">{{t('RESERVE YOUR CHAIR')}}<span aria-hidden="true">↗</span></a></section>
<section id="experience" class="wire-experience"><div class="wire-experience-upper"><div class="wire-experience-copy"><span class="wire-gray-chip">{{t('01 / THE PRIVATE RITUAL')}}</span><div class="wire-white-lines"><span>{{t('A RITUAL,')}}</span><span>{{t('CUT TO YOU.')}}</span><span>{{t('NEVER RUSHED.')}}</span></div></div><div class="wire-experience-photo"><img src="https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=900&q=85&fit=crop" :alt="t('Barber working with precision')" loading="lazy"></div></div><div class="wire-experience-lower"><div class="wire-inset-photo"><img src="https://images.unsplash.com/photo-1593702295094-aea22597af65?w=900&q=85&fit=crop" :alt="t('Traditional barber tools')" loading="lazy"></div><div class="wire-experience-description wire-white-lines"><span>{{t('A PRIVATE CONSULTATION.')}}</span><span>{{t('MASTERFUL ATTENTION TO DETAIL.')}}</span><span>{{t('TIME WELL SPENT.')}}</span></div></div></section>
<section id="services" class="wire-services"><div class="wire-title-bars"><h2>{{t('GROOMING, ELEVATED')}}</h2><p>{{t('A HIGHER STANDARD. NEVER RUSHED.')}}</p></div><div class="wire-service-main"><div class="wire-service-photo"><img src="https://images.unsplash.com/photo-1621605815971-fbc98d665033?w=1000&q=85&fit=crop" :alt="t('Barber shaping a haircut')" loading="lazy"></div><div class="wire-service-copy"><div class="wire-service-options" role="group" :aria-label="t('Choose a service')"><button v-for="s in services" :key="s.id" class="wire-service-option" :class="{active:serviceId===s.id}" :aria-pressed="serviceId===s.id" @click="serviceId=s.id"><span>{{t(s.name).toUpperCase()}} · ${{s.price}}</span><small>{{s.duration}} min · {{t(s.detail)}}</small></button><span class="wire-service-tagline">{{t('EXCEPTIONAL BY DESIGN.')}}</span></div></div></div></section>
<section id="artists" class="wire-artists"><div class="wire-artists-heading wire-white-lines"><span>{{t('MASTER BARBERS')}}</span><span>{{t('PERSONAL SERVICE.')}}</span></div><div class="wire-artists-stage"><div class="wire-artist-roster" role="group" :aria-label="t('Our barbers')"><p v-if="!team" :role="teamError?'alert':'status'">{{t(teamError||'Loading team…')}}</p><button v-for="person in team||[]" :key="person.id" class="wire-barber-option" :class="{active:barberId===person.id}" :disabled="!person.serviceIds.length" :aria-pressed="barberId===person.id" @click="choose(person)"><span class="wire-barber-portrait"><img :src="person.image" :alt="t('Portrait of')+' '+person.name" loading="lazy"></span><strong>{{person.name}}</strong><small>{{t(person.role)}}<span v-if="!person.serviceIds.length" class="team-unavailable">{{t('Not currently accepting bookings')}}</span></small></button></div><div class="wire-artist-frame" aria-hidden="true"></div><a href="#book" class="wire-wide-cta">{{language==='es'?'RESERVAR CON':'BOOK WITH'}} {{(barber?.name||t('Choose a service')).toUpperCase()}} <span aria-hidden="true">↗</span></a></div></section>
<section id="book" class="booking-section"><div class="section-wrap booking-layout"><div class="booking-aside"><p class="eyebrow">{{t('YOUR TIME, YOUR CHAIR')}}</p><h2>{{t('MAKE IT')}}<br><em>{{t('YOURS.')}}</em></h2><p>{{t('A private consultation, a master barber, and an appointment shaped around you.')}}</p><div class="booking-rule"></div><p class="booking-detail">{{t('NEW YORK CITY')}}<br>{{t('Monday–Saturday · 8:30 AM – 7 PM')}}<br>{{t('Sunday · 9 AM – 5 PM')}}<br><a href="#location">{{t('View location')}} ↗</a></p></div><div class="booking-card"><div class="booking-card-heading"><span>{{t('04 / RESERVATIONS')}}</span><h3>{{t('Reserve your appointment')}}</h3></div><div v-if="success" class="confirmation" role="status"><span>{{t('✦ BOOKING CONFIRMED')}}</span><p>{{t(services.find(s=>s.id===success.serviceId)?.name||'')}} · {{success.name}} · {{success.date}} · {{pretty(success.time)}}<br>{{language==='es'?'Referencia':'Booking reference'}}: {{success.id.slice(0,8).toUpperCase()}}</p><button @click="success=null">{{t('Make another reservation')}}</button></div><form v-else @submit.prevent="book"><p class="booking-selection" aria-live="polite">{{t(service.name)}} · {{barber?.name||t('No professional available')}}<span>${{service.price}} · {{service.duration}} min</span></p><span class="field-label">{{t('01 — SELECT A SERVICE')}}</span><div class="choice-grid"><button v-for="s in services" :key="s.id" type="button" class="choice" :class="{selected:serviceId===s.id}" :aria-pressed="serviceId===s.id" @click="serviceId=s.id"><span>{{t(s.name)}}</span><small>${{s.price}} · {{s.duration}} min</small></button></div><span class="field-label">{{t('02 — CHOOSE YOUR BARBER')}}</span><div class="barber-choice"><p v-if="!team" role="status">{{t(teamError||'Loading team…')}}</p><p v-else-if="!eligible.length" role="status">{{t('No professional is currently enabled for this service. Choose another service.')}}</p><button v-for="b in eligible" :key="b.id" type="button" class="barber-pill" :class="{selected:barberId===b.id}" :aria-pressed="barberId===b.id" @click="preferred=b.id"><img :src="b.image" alt=""><span>{{b.name}}</span></button></div><div class="date-row"><label><span class="field-label">{{t('03 — SELECT A DATE')}}</span><input v-model="date" type="date" :min="today()" required :aria-label="t('Appointment date')"></label></div><span class="field-label">{{t('04 — AVAILABLE TIMES · NEW YORK TIME')}}</span><div class="time-grid" role="group" :aria-label="t('Available times')"><p v-if="loading" class="muted">{{t('Checking availability…')}}</p><template v-else-if="slots.length"><button v-for="slot in slots" :key="slot" type="button" :class="{selected:time===slot}" :aria-pressed="time===slot" @click="time=slot">{{pretty(slot)}}</button></template><p v-else class="muted">{{t('No available times. Please choose another date.')}}</p></div><div class="input-grid"><label>{{t('Full name')}}<input v-model="customer.name" required minlength="2" maxlength="80" autocomplete="name"></label><label>{{t('Email address')}}<input v-model="customer.email" type="email" required maxlength="120" autocomplete="email"></label><label class="full">{{t('Phone number')}}<input v-model="customer.phone" type="tel" required minlength="7" maxlength="25" autocomplete="tel"></label><label class="full">{{t('Anything we should know?')}}<textarea v-model="customer.notes" maxlength="500" rows="3"></textarea></label></div><p v-if="error" class="form-error" role="alert">{{t(error)}}</p><button class="submit-button" :disabled="busy||!time||!barberId||!!teamError">{{busy?t('Saving…'):(language==='es'?'CONFIRMAR RESERVA':'CONFIRM RESERVATION')}} · ${{service.price}} <span aria-hidden="true">↗</span></button><p class="form-foot">{{t('No payment is collected online. Your appointment is reserved immediately.')}}</p></form></div></div></section>
<section id="location" class="location-section"><div class="location-copy"><p class="eyebrow">{{t('Visit us')}}</p><h2>Steve's Barbershop</h2><p>{{t('Find us on Google Maps')}}</p><a class="gold-button" href="https://maps.app.goo.gl/ahaUnBhazULqv9YEA" target="_blank" rel="noopener noreferrer">{{t('Get directions')}} <span aria-hidden="true">↗</span></a></div><iframe src="https://www.google.com/maps?q=40.6947579,-73.849297&z=17&output=embed" :title="t('Find us on Google Maps')" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></section>
<footer><div class="section-wrap footer-inner"><a class="brand footer-brand" href="#top"><BrandLogo /><span>Steve's Barbershop<small>{{t('BARBER · NEW YORK')}}</small></span></a><span>{{t('GROOMING IS PERSONAL.')}}</span><a href="https://www.instagram.com/stevesbarbershop96th/" target="_blank" rel="noopener noreferrer" aria-label="Instagram: @stevesbarbershop96th">Instagram · @stevesbarbershop96th ↗</a><a href="https://maps.app.goo.gl/ahaUnBhazULqv9YEA" target="_blank" rel="noopener noreferrer">Google Maps ↗</a><a href="/staff">{{t('Staff appointments')}}</a></div></footer>
</main>
</template>
